entries[141294] = { ["name"] = "Zeichen von Orgrimmar", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\n\"Wird den Kriegern der Horde verliehen, die sich mutig in die Schlacht an der Verheerten Küste stürzen.\"\nVerkaufspreis:" }
entries[141295] = { ["name"] = "Außerordentlich dickes Mojo", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Trinkt das Mojo, um 5 Min. lang alle 3 Sek. 5% Gesundheit wiederherzustellen und Angreifern Naturschaden zuzufügen. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\n\"Riecht frisch.\"\nVerkaufspreis:" }
entries[141296] = { ["name"] = "Uraltes Manabecken", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erschafft für 2 Min. ein schwebendes Manabecken. Gruppen- und Schlachtzugsmitglieder können das Becken verwenden, um einen Manakatalysator zu erhalten, der den Effekt herbeigezauberter Nahrung sowie in Suramar gekaufter magischer Nahrung erhöht. (1 Stunde Abklingzeit)" }
entries[141297] = { ["name"] = "Arkandusche", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt für 2 Min. die Arkandusche auf. Die arkanen Ströme reinigen nicht nur durch Kleidung hindurch, sie reinigen die Kleidung auch gleich mit! (1 Stunde Abklingzeit)" }
entries[141298] = { ["name"] = "Entrückender Meditationsstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Fokussiert Euch auf den Stein und denkt an etwas Schönes. (1 Stunde Abklingzeit)" }
entries[141299] = { ["name"] = "Lichtkugel der Kaldorei", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert für 1 Min. eine Lichtkugel der Kaldorei. (1 Stunde Abklingzeit)" }
entries[141300] = { ["name"] = "Fokussierkristall der Magier", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Fokussiert das, was einst ein mächtiger Arkanstrahl war, auf Ziele vor Euch. (3 Min Abklingzeit)" }
entries[141301] = { ["name"] = "Instabile Puderdose", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Öffnet die ominös leuchtende Puderdose." }
entries[141302] = { ["name"] = "Eisseelenanhänger", ["text"] = "Questgegenstand\n\"Die gefrorene Seele von Lysande, die ihre Königin so sehr liebte, dass sie sich selbst opferte, um zur Inkarnation der Rache zu werden.\"" }
