entries[141307] = { ["name"] = "Schlagendes Teufelsherz", ["text"] = "Questgegenstand\n\"Das riesige, fahl grüne Herz schlägt noch in Eurer Hand...\"" }
entries[141308] = { ["name"] = "Dämonische Eingeweide", ["text"] = "Questgegenstand\n\"Die verrottenden, gewundenen Innereien eines mächtigen Dämons.\"" }
entries[141309] = { ["name"] = "Auge der Wächterin", ["text"] = "Questgegenstand\n\"Cordana beobachtet Euch...\"" }
