entries[141311] = { ["name"] = "Vorlage: Massensondierung von Leystein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man mehrere Chargen Leysteinerz auf einmal sondiert.\nSondiert mehrere Chargen Leysteinerz auf einmal.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nLeysteinerz\nHandwerksmaterial\nVerkaufspreis:\nBenötigt Leysteinerz (20)" }
entries[141312] = { ["name"] = "Vorlage: Massensondierung von Teufelsschiefer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man mehrere Chargen Teufelsschiefer auf einmal sondiert.\nSondiert mehrere Chargen Teufelsschiefer auf einmal.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nVerkaufspreis:\nTeufelsschiefer\nHandwerksmaterial\nVerkaufspreis:\nBenötigt Teufelsschiefer (20)" }
entries[141313] = { ["name"] = "Manadurchsetzter Eiersack der Fal'dorei", ["text"] = "Wird beim Aufheben gebunden\n\"Als der vorherige Baum explodierte, wurden viele Kreaturen von der arkanen Macht erfasst.\"\nVerkaufspreis:" }
entries[141314] = { ["name"] = "Gefäß des Baumheilers", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Behältnis war eine der vielen Ritualkomponenten, die bei den Baumheilern zum Einsatz kamen, als sie den ersten Manabaum großzogen.\"\nVerkaufspreis:" }
entries[141316] = { ["name"] = "Seltsames Murlocei", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Squirky beschwört.\nMit Rechtsklick Squirky den Babymurloc beschwören oder wieder freigeben.\n80 ( 80)" }
entries[141317] = { ["name"] = "Machtvoller Manaedelstein", ["text"] = "Questgegenstand\n\"Dieser Edelstein pulsiert vor Mana.\"" }
entries[141318] = { ["name"] = "Pfosten des Zorns", ["text"] = "Einzigartig (20)\nBenutzen: Stellt einen Pfosten auf, der mit einer geschnitzten Maske verziert ist, die Wut darstellt.\nVerkaufspreis:" }
entries[141319] = { ["name"] = "Pfosten des Glücks", ["text"] = "Einzigartig (20)\nBenutzen: Stellt einen Pfosten auf, der mit einer geschnitzten Maske verziert ist, die Freude darstellt.\nVerkaufspreis:" }
