entries[141321] = { ["name"] = "Symmetrie der Shivarra", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\nAnlegen: Nach der Aktivierung von 'Klingenwirbel' fügen Nahkampfangriffe allen Gegnern in der Nähe 3 Sek. lang 39% des normalen Schadens zu.\n\"Die Shivarra gelten allgemein als mindestens dreimal so fanatisch wie die anderen Mitglieder der Brennenden Legion.\"\nVerkaufspreis:" }
entries[141322] = { ["name"] = "Glänzende silberne Halskette", ["text"] = "Hals\nVerkaufspreis:" }
entries[141323] = { ["name"] = "Wilde Transmutation", ["text"] = "\"Was werdet Ihr bekommen?\"" }
entries[141324] = { ["name"] = "Talisman der Shal'dorei", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\n\"Dieses Relikt strahlt Macht aus und ermöglicht es seinem Nutzer, die Teleporter der Nachtfestung zu verwenden.\"\nVerkaufspreis:" }
