entries[141327] = { ["name"] = "Funktionierender Zauberschutz", ["text"] = "Questgegenstand\n\"Scheint intakt und in gutem Zustand zu sein.\"" }
entries[141328] = { ["name"] = "Ritualnotizen", ["text"] = "Questgegenstand\n\"Dieser Stapel Papiere beschreibt detailreich ein mächtiges Schutzritual.\"" }
entries[141329] = { ["name"] = "Ritualfokuskristall", ["text"] = "Questgegenstand\n\"Dieser Kristall scheint sehr fein gearbeitet zu sein.\"" }
entries[141330] = { ["name"] = "Dämonenstein", ["text"] = "Questgegenstand\n\"Dieser glühende Stein schimmert vor außerweltlicher Strahlung.\"" }
entries[141331] = { ["name"] = "Phiole mit grünem Schleim", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bespritzt Euch selbst mit dem Schleim, der Euch in einen Lepragnom verwandelt. (10 Min Abklingzeit)\n\"Es ist umkehrbar. Vielleicht hat Thermadraht ja tatsächlich an einem Heilmittel gearbeitet...\"\nVerkaufspreis:" }
entries[141332] = { ["name"] = "Die Annalen von Licht und Schatten", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Priester\n\"Die zwölf Bände beschreiben detailreich alles Wissenswerte über die Konklave und ihre Mitglieder. Archivar Tintenschmiede scheint sehr daran interessiert zu sein, die komplette Sammlung zu bergen.\"" }
entries[141333] = { ["name"] = "Kodex des ruhigen Gemüts", ["text"] = "Benutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln. Funktioniert nicht bei Zielen über Stufe 50.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[141334] = { ["name"] = "Mächtiger Sauereientferner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Trinkt das Gebräu, das Euch sofort verschwinden und für 10 Sek. in Verstohlenheit übergehen lässt. Jede Aktion bricht den Effekt ab. Kann nur im Kampf eingesetzt werden.\n\"Praktisch zum Entfernen von unbeabsichtigten Sauereien. Auch praktisch zum Entfernen der eigenen Person vom Schauplatz unbeabsichtigter Sauereien.\"" }
entries[141335] = { ["name"] = "Verlorene Forschungsnotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lesen, um neues Wissen über Euer Artefakt zu erlangen und die Rate zu erhöhen, mit der Ihr Artefaktmacht erlangt.\n\"Diese einwandfrei erhaltenen Notizen über uralte Waffen stammen vom alten Fillmaff und wurden von einem nachlässigen Kurier fallen gelassen.\"" }
