entries[141587] = { ["name"] = "Königin Yh'saeries Anhänger", ["text"] = "Wird beim Anlegen gebunden\nHals\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\n\"Yh'saerie regierte gemeinsam mit Than Kray-Tan. Ihr umsichtiges Urteilsvermögen brachte ihrem Klan sogar in Kriegszeiten Wohlstand.\"\nVerkaufspreis:" }
entries[141588] = { ["name"] = "Talisman von Jaimil Lichtherz", ["text"] = "Wird beim Anlegen gebunden\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 10.\n+ 4 Vielseitigkeit\n\"Jaimils unerschütterlicher Glaube an das Licht führte Gorrog zur ihr und beschützte sie während der Zerschlagung.\"\nVerkaufspreis:" }
entries[141589] = { ["name"] = "Treias handgewebtes Tuch", ["text"] = "Wird beim Anlegen gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\n\"Gewirkt aus reinstem Sternenlicht.\"\nVerkaufspreis:" }
entries[141590] = { ["name"] = "Umhang von Martayl Meeresschreiter", ["text"] = "Wird beim Anlegen gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\n+ 2 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 4.\n\"Ein Andenken an Martayls bizarre Reise.\"\nVerkaufspreis:" }
entries[141591] = { ["name"] = "Technik: Kodex des ruhigen Gemüts", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Kodex des ruhigen Gemüts effizienter herstellt.\nStellt einen Kodex des ruhigen Gemüts her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nKodex des ruhigen Gemüts\nBenutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln. Funktioniert nicht bei Zielen über Stufe 50.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Fahle Pigmente (5), Rosenrote Pigmente (15)" }
entries[141592] = { ["name"] = "Technik: Kodex des ruhigen Gemüts", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Kodex des ruhigen Gemüts äußerst effizient herstellt.\nStellt einen Kodex des ruhigen Gemüts her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nKodex des ruhigen Gemüts\nBenutzen: Stellt einen Kodex auf, der es Spielercharakteren in der Nähe gestattet, ihre Talente zu wechseln. Funktioniert nicht bei Zielen über Stufe 50.\n\"Wird von Spielercharakteren erstellt, die den Beruf Inschriftenkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Leichtes Pergament (50), Fahle Pigmente (5), Rosenrote Pigmente (5)" }
