entries[141849] = { ["name"] = "Bauplan: Reaves-Modul: Blingmodus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Reaves-Modul: Blingmodus herstellt.\nStellt ein Reaves-Modul: Blingmodus her.\nBenötigt Ingenieurskunst der Verheerten Inseln (100)\nVerkaufspreis:\nReaves-Modul: Blingmodus\nBenutzen: Lehrt Reaves, den Blingmodus zu aktivieren.\nVerkaufspreis:\nBenötigt Teufelsschiefer (80), Wutstein (2), Blingtron-Schaltplandesignanleitung (5)" }
entries[141850] = { ["name"] = "Muster: Urhornzaumzeug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Urhornzaumzeug herstellt.\nStellt ein Urhornzaumzeug her.\nBenötigt Lederverarbeitung der Verheerten Inseln (100)\nVerkaufspreis:\nUrhornzaumzeug\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr ein großes Nordurhorn beschwört. Das ist ein Bodenreittier.\nGroßes Nordurhorn : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Lederverarbeitung der Verheerten Inseln (100)\nBenötigt Unerfahrenes Reiten\n\n\"Eine der wackersten Spezies, die auf den Hängen des Hochbergs hausen. Sie können monatelang in eisigen Blizzards überleben.\"\nBeruf:\nLederverarbeitungBenötigt Steinbalgleder (50), Blut von Sargeras (25), Teufelsbalg (10)" }
