entries[142049] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Karazhan\nHerbeigezauberter Gegenstand\nEinzigartig\nBenutzen: Bricht das Siegel des Buches. Wenn Eure Gesundheit unter 25% fällt, werden für 1 Stunde Euer verursachter Schaden und Eure erhaltene Heilung erhöht.\n\"Die Essenz dieses Buchs ist an Karazhan gebunden.\"" }
