entries[142119] = { ["name"] = "Rezept: Trank der verlängerten Macht", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines Tranks der verlängerten Macht.\nStellt einen Stapel aus 10 Tränken der verlängerten Macht an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTrank der verlängerten Macht\nBenutzen: Trinkt dies, um alle Werte für 1 Min. um 88 zu erhöhen. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Blut von Sargeras , Kristallphiole (10)" }
entries[142120] = { ["name"] = "Rezept: Trank der verlängerten Macht", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der verlängerten Macht noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Die Nachtsüchtigen\n- Respektvoll\nVerkaufspreis:\nTrank der verlängerten Macht\nBenutzen: Trinkt dies, um alle Werte für 1 Min. um 88 zu erhöhen. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Blut von Sargeras , Kristallphiole (10)" }
entries[142121] = { ["name"] = "Rezept: Trank der verlängerten Macht", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der verlängerten Macht noch effizienter herstellt.\nChance auf die Herstellung von mehr als 10 Tränken.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTrank der verlängerten Macht\nBenutzen: Trinkt dies, um alle Werte für 1 Min. um 88 zu erhöhen. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Blut von Sargeras , Kristallphiole (10)" }
