entries[142154] = { ["name"] = "Armreife der bekümmerten Braut", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[142156] = { ["name"] = "Kiste mit Ordensressourcen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhaltet 200 Ordensressourcen." }
entries[142157] = { ["name"] = "Arans Entspannungsrubin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, unter Eurem Ziel einen Flammenkranz zu erschaffen. Nach 6 Sek. oder wenn der Gegner den Kranz verlässt, explodiert er und fügt allen Gegnern innerhalb von 12 Metern [ 99 * (1 + Vielseitigkeit)] Feuerschaden zu.\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142158] = { ["name"] = "Prüfung des Glaubens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Schleudert im Verlauf von 6 Sek. 12 heilige Blitze auf verwundete Verbündete innerhalb von 15 Metern, die sie pro Blitz um 18 Gesundheit heilen. (1 Min, 30 Sek. Abklingzeit)\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142159] = { ["name"] = "Blutbeflecktes Taschentuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nBenutzen: Erdrosselt Euer Ziel von hinten, sodass es alle 3 Sek. 4 körperlichen Blutungsschaden erleidet, bis es stirbt. (1 Min Abklingzeit)\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142160] = { ["name"] = "Mrrgrias Gunst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nBenutzen: Markiert einen Gegner mit einem Donnerritual und verursacht nach 3 Sek. 69 Naturschaden. Wenn der Gegner von 'Flammensturm' betroffen ist, verursacht 'Donnerritual' 30% mehr Schaden und betäubt für 3 Sek. (30 Sek. Abklingzeit)\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142161] = { ["name"] = "Unentrinnbarer Schrecken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Eure Angriffe haben eine Chance, eine körperlose Präsenz zu beschwören, die Euer Ziel heimsucht und 12 Sek. lang den Schaden seiner automatischen Angriffe gegen Euch um bis zu 214 pro Schlag verringert.\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142162] = { ["name"] = "Schwingende Energie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, in der Nähe ungebundenes Mana zu erschaffen, das 30 Sek. lang bestehen bleibt. Durch Kontakt damit stellt Ihr 58 Mana wieder her.\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142164] = { ["name"] = "Jettonys Versprechen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Erschafft einen Flammensturm am Standort des Gegners und verursacht im Verlauf von 8 Sek. ( 10 * 8) Feuerschaden. Wenn 'Flammensturm' einen Gegner trifft, der von 'Donnerritual' betroffen ist, wird der Schaden von 'Flammensturm' um 30% und sein Radius um 50% erhöht. (1 Min Abklingzeit)\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142165] = { ["name"] = "Zersetzter Konstruktkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, eine Sphäre unsteter Energie auf Euer Ziel zu entfesseln, die ihm und allen Gegnern, die sie durchdringt, 28 Schaden zufügt.\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142166] = { ["name"] = "Ätherische Urne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke oder Intelligenz]\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Entfernt sofort alle Furchteffekte. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[142167] = { ["name"] = "Auge des Befehls", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Eure automatischen Nahkampfangriffe erhöhen Euren kritischen Trefferwert 10 Sek. lang um 1 . Dieser Effekt ist bis zu 10-mal stapelbar und wird zurückgesetzt, wenn Ihr ein neues Ziel angreift.\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142168] = { ["name"] = "Essensglöckchen des Majordomus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Ausdauer\nBenutzen: Erhöht einen zufälligen Sekundärwert für 15 Sek. um 39 . (1 Min, 30 Sek. Abklingzeit)\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
entries[142169] = { ["name"] = "Rabenphantom", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Ausdauer\nErhöht Eure Meisterschaftswertung um + 6.\nBenutzen: Beschwört einen Wächterfamiliar, der 20 Sek. lang über bis zu 4 Verbündete in der Nähe wacht. Überträgt 50% des von jedem Verbündeten erlittenen Schadens auf Euch, bis zu maximal 52 Schaden pro Ziel. (2 Min Abklingzeit)\n\"Mit der Silhouette eines Raben markiert.\"\nVerkaufspreis:" }
