entries[142206] = { ["name"] = "Umhang der schwelenden Flamme", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nAnlegen: Wenn Ihr Feuerschaden erleidet, wird Eure Geschwindigkeit 3 Sek. lang um 20 erhöht. Kann nur einmal alle 10 Sek. auftreten. (10s Abklingzeit)\nVerkaufspreis:" }
entries[142207] = { ["name"] = "Amulett des letzten Wächters", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure Tempowertung um + 10.\n+ 4 Vielseitigkeit\nBürde der Macht (0/2)\nAmulett des letzten Wächters\nWeinbefleckter Mantel\n(2) Set : Das Bezwingen eines Dungeonbosses von Legion erhöht Euren Schaden und Eure Heilung 2 Min. lang um 10%.\nVerkaufspreis:" }
