entries[142209] = { ["name"] = "Einladung zum Abendessen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Lädt einen Gast zum Dinner ein, damit er Eure Champions auf Missionen begleitet." }
