entries[142212] = { ["name"] = "Vorläufer eines Konstrukts der Nachtgeborenen", ["text"] = "Questgegenstand\nEinzigartig\n\"Wenn Ihr ganz genau hinhört, könnt Ihr tief im Inneren beinahe eine melodische Stimme hören.\"" }
