entries[142214] = { ["name"] = "7.1 Dungeon - Karazhan - Cloth SHOULDER 2", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nVerkaufspreis:" }
entries[142215] = { ["name"] = "Weinbefleckter Mantel", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\n\"Das Erinnerungsstück an eine unvergessliche Nacht.\"\n\nBürde der Macht (0/2)\nAmulett des letzten Wächters\nWeinbefleckter Mantel\n(2) Set : Das Bezwingen eines Dungeonbosses von Legion erhöht Euren Schaden und Eure Heilung 2 Min. lang um 10%.\nVerkaufspreis:" }
entries[142216] = { ["name"] = "Waffen der Nachtgeborenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert eine Waffenkiste auf dem Boden, die alle rebellischen Bürger innerhalb von 3 Metern bewaffnet. (10 Sek. Abklingzeit)" }
entries[142223] = { ["name"] = "Junger Sonnenflitzer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren jungen Sonnenflitzer beschwören oder wieder freigeben.\n80 ( 80)" }
entries[142225] = { ["name"] = "Ban-Lu, Begleiter des Großmeisters", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Begleiter Ban-Lu oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Xuens Kind Ban-Lu hat jedem Großmeister viele Jahre treu gedient.\"\nQuest:\nDie Prüfung des Ban-Lu" }
entries[142226] = { ["name"] = "Vertrauen eines wilden Wolfsfalken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen reitbaren wilden Wolfsfalken des Meisterjägers beschwört.\nBeschwört Euren wilden Wolfsfalken des Meisterjägers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Knäuel aus Krallen und Klauen, das fliegen und schwimmen kann. Niemand ist davor sicher.\"\nVerkäufer:\nPan die sanfte Hand\nZone:\nDie Volltrefferhütte" }
entries[142227] = { ["name"] = "Vertrauen eines treuen Wolfsfalken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen reitbaren treuen Wolfsfalken des Meisterjägers beschwört.\nBeschwört Euren treuen Wolfsfalken des Meisterjägers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Geist des großen Jägers hat Euch als würdig erachtet. Seine Kinder werden von nun an auf ewig Eurem Ruf folgen.\"\nQuest:\nNacht der Wildnis" }
entries[142228] = { ["name"] = "Vertrauen eines schrecklichen Wolfsfalken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen reitbaren schrecklichen Wolfsfalken des Meisterjägers beschwört.\nBeschwört Euren schrecklichen Wolfsfalken des Meisterjägers oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Apportiert mit hoher Wahrscheinlichkeit den Kopf eines kleinen Säugetiers oder Humanoiden.\"\nVerkäufer:\nPan die sanfte Hand\nZone:\nDie Volltrefferhütte" }
entries[142231] = { ["name"] = "Verrottende Zügel des Giftbrutbezwingers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Giftbrutbezwinger des Todesgebieters beschwört.\nBeschwört Euren Giftbrutbezwinger des Todesgebieters oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein mächtiger roter Großdrache, der von seiner eigenen Lebensenergie zum Untod erweckt wurde. Wahrhaft eine Verhöhnung des Lebens.\"\nQuest:\nDer Verlorene Gletscher" }
entries[142232] = { ["name"] = "Eiserne Zügel des blutrünstigen Kriegswyrms", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen blutrünstigen Kriegswyrm des Schlachtenfürsten beschwört.\nBeschwört Euren blutrünstigen Kriegswyrm des Schlachtenfürsten oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Hört auch auf \"Herr Beißi\".\"\nQuest:\nDie Prüfung des Zorns" }
entries[142233] = { ["name"] = "Schattenhafte Zügel des verfluchten Zornrosses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein verfluchtes Zornross des Netherfürsten beschwört.\nBeschwört Euer verfluchtes Zornross des Netherfürsten oder gibt es wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Schatten und Flamme, was kann da schon schiefgehen?\"\nBeute von:\nLord Hel'nurath\nZone:\nDie Verheerte Küste" }
entries[142234] = { ["name"] = "Boshafter Kriegsbär", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegsbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Fast doppelt so boshaft wie sein Pendant bei der Horde.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[142235] = { ["name"] = "Boshafter Kriegsbär", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegsbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Fast doppelt so boshaft wie sein Pendant bei der Allianz.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
entries[142236] = { ["name"] = "Mittnachts ewige Zügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Mittnacht beschwört.\nBeschwört Mittnacht oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Noch immer eins der bösartigsten Pferde in den Stallungen von Karazhan.\"\nBeute von:\nAttumen der Jäger\nOrt:\nRückkehr nach Karazhan" }
entries[142237] = { ["name"] = "Boshafter Kriegslöwe", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegslöwen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Bei der Zähmung dieses Reittiers sind zahlreiche Knappen zu Schaden gekommen.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[142238] = { ["name"] = "Unglaubliche Monster und wo sie zu finden sind", ["text"] = "Questgegenstand\n\"Eine Kopie dieses Schriftstücks befindet sich in der Stube von fast jedem Magier in Azeroth.\"" }
entries[142239] = { ["name"] = "Handbuch der gefiederten Freunde", ["text"] = "Questgegenstand\n\"Auf dem Einband steht, dass das Wort 'Freunde' nicht zu wörtlich interpretiert werden sollte.\"" }
