entries[142246] = { ["name"] = "Beschädigte Taschenuhr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Uhr ist zerkratzt und kaputt. Es scheint sich ein zusammengeknüllter Notizzettel darin zu befinden.\"" }
entries[142247] = { ["name"] = "99.0 [reuse me]", ["text"] = "Questgegenstand" }
entries[142248] = { ["name"] = "Höchstexquisiter Stinkekäse", ["text"] = "Questgegenstand\n\"Der Duft treibt einem die Tränen in die Augen.\"" }
