entries[142250] = { ["name"] = "Aegwynn und die Drachenjagd", ["text"] = "Wird beim Aufheben gebunden\nDauer: 2 std. (Realzeit)\n\"Ein Exemplar, das Erzmagier Newhearth von den Kuratoren in Auftrag gegeben hat. Ihr braucht nicht daran zu denken, es zurückzugeben, denn das erledigt es von selbst.\"\n<Zum Lesen rechtsklicken>" }
entries[142251] = { ["name"] = "Ly'leths Sendschreiben", ["text"] = "Questgegenstand\n\"Obwohl es hastig geschrieben wurde, sind Ly'leths Handschrift und Schreibstil hervorragend.\"\n<Zum Lesen rechtsklicken>" }
