entries[142262] = { ["name"] = "Elektrisierter Schlüssel", ["text"] = "Benutzen: Aktiviert eine inaktive Arachnodrohne. (10 Sek. Abklingzeit)\n\"Das war in seiner Tasche?\"\nVerkaufspreis:" }
