entries[142321] = { ["name"] = "Säbel der Schwarzen Klinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 1.\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[142322] = { ["name"] = "Lichtaus", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig (2)\nBenutzen: Ein starkes alkoholisches Getränk." }
entries[142323] = { ["name"] = "Barbarenbowle", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig (2)\nBenutzen: Ein typisches alkoholisches Getränk." }
