entries[142325] = { ["name"] = "Uralter Kampfgildenheiltrank", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Stellt 6000 Gesundheit wieder her. Kann nur in einer Arena der Kampfgilde verwendet werden. (5 Min Abklingzeit)" }
entries[142326] = { ["name"] = "Kampfgildentrank der verlängerten Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Trinken, um alle Werte für 1 Min. um 106 zu erhöhen. Kann nur in einer Arena der Kampfgilde verwendet werden. (5 Min Abklingzeit)" }
entries[142327] = { ["name"] = "Teufelskristallfragment", ["text"] = "Questgegenstand\n\"Die Überreste des Kristalls fühlen sich warm an.\"" }
entries[142328] = { ["name"] = "Fragment der Bösartigkeit", ["text"] = "Questgegenstand\n\"Die hasserfüllten Schreie aus dem Inneren des Fragments brennen sich in Eure Hand ein.\"" }
entries[142329] = { ["name"] = "Fragment der Folter", ["text"] = "Questgegenstand\n\"Gequältes Flüstern ertönt aus dem Inneren und verbreitet eine abschreckende Aura um das Fragment herum.\"" }
entries[142330] = { ["name"] = "Fragment der Macht", ["text"] = "Questgegenstand\n\"Die aus dem Fragment strömende Macht ist überwältigend.\"" }
entries[142331] = { ["name"] = "Rezept: Würziges Falkosaurieromelett", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen:\nBereitet ein würziges Falkosaurieromelett zu.\nBenötigt Kochkunst der Verheerten Inseln (1)\nBenötigt Die Wächterinnen\n- Respektvoll\nVerkaufspreis:\nWürziges Falkosaurieromelett\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und könnt nach dem Töten eines Gegners für kurze Zeit schneller laufen und angreifen. Kann nur auf den Verheerten Inseln genutzt werden.\nVerkaufspreis:\nBenötigt Falkosaurierei (2)" }
entries[142332] = { ["name"] = "Luffaschwamm mit Federn", ["text"] = "Benutzen: Heilt 1575 Gesundheit und entfernt Blutungen. Kann nur auf den Verheerten Inseln genutzt werden.\n10 Aufladungen\nVerkaufspreis:" }
entries[142334] = { ["name"] = "Würziges Falkosaurieromelett", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und könnt nach dem Töten eines Gegners für kurze Zeit schneller laufen und angreifen. Kann nur auf den Verheerten Inseln genutzt werden.\nVerkaufspreis:" }
entries[142335] = { ["name"] = "Makellose Falkosaurierfeder", ["text"] = "Handwerksmaterial\n\"Unzerzaust.\"\nVerkaufspreis:" }
entries[142336] = { ["name"] = "Falkosaurierei", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[142337] = { ["name"] = "Pläne: Verseuchung", ["text"] = "Benutzen: Lehrt Euch die Herstellung von Verseuchung.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nVerseuchung\nWird beim Anlegen gebunden\nZweihändig Stangenwaffe\n6 - 11 Schaden Geschwindigkeit 3.60\n(2.4 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nTrefferchance: Lässt ein Ziel erkranken und fügt so im Verlauf von 10 Sek. 1 Naturschaden sowie insgesamt 1 zusätzlichen Schaden zu.\nVerkaufspreis:\nBenötigt Mithrilbarren (28), Sekret des Untodes (10), Echtsilberbarren (10), Robuster Schleifstein (6), Dickes Leder (6)\nOptionale Reagenzien: [] (#50)" }
entries[142338] = { ["name"] = "Normaler Karazhangegenstand", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[142339] = { ["name"] = "Heroischer Karazhangegenstand", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[142340] = { ["name"] = "Thar'zuls Kopf", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein grausiger Beweis von der Invasion von Karazhan.\"" }
entries[142341] = { ["name"] = "Liebesboot", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört Euer Liebesboot auf der Wasseroberfläche innerhalb von 20 Metern.\nWährend 'Liebe liegt in der Luft' aktiv ist, ist die Abklingzeit verringert. (30 Min Abklingzeit)\n\"Die romantischste Kreuzfahrt in Azeroth.\"" }
entries[142342] = { ["name"] = "Schimmerndes Bündel", ["text"] = "Wird beim Aufheben gebunden\n\"Der Inhalt scheint von einigen mächtigen Zaubern verstärkt worden zu sein.\"\n<Zum Öffnen rechtsklicken>" }
entries[142343] = { ["name"] = "Kinetischer Reißer", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Faustwaffe\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[142344] = { ["name"] = "Gebrochene Axtklinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Schmiedekunst (1)" }
entries[142345] = { ["name"] = "Axtklinge", ["text"] = "Questgegenstand\n\"Die abgebrochene Klinge der Axt eines Ogers der Feuermägen.\"" }
entries[142346] = { ["name"] = "Pläne: Kahlholzhacke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Kahlholzhacke.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nKahlholzhacke\nWird beim Anlegen gebunden\nZweihändig Axt\n5 - 12 Schaden Geschwindigkeit 3.60\n(2.4 Schaden pro Sekunde)\n+2 Stärke\n+1 Ausdauer\nHaltbarkeit 95 / 95\nVerkaufspreis:\nBenötigt Thoriumbarren (30), Essenz des Lebens (6), Wildranke (6), Großer Opal (6), Verdichteter Schleifstein (2), Unverwüstliches Leder (8)\nOptionale Reagenzien: [] (#50)" }
entries[142349] = { ["name"] = "Blutbeschmiertes Bandana der Defias", ["text"] = "Questgegenstand" }
entries[142350] = { ["name"] = "Börse des Herausforderers", ["text"] = "Wird beim Aufheben gebunden\n\"Euer Anteil am 'Preisgeld' und was sonst noch auf dem Boden der Arena herumlag.\"\n<Zum Öffnen rechtsklicken>" }
entries[142351] = { ["name"] = "Schwarzfelsrubin", ["text"] = "Questgegenstand\n\"Diesem Rubin entströmt warme Energie. Zugleich ist er einer der seltensten und am schwersten herzustellenden Edelsteine seiner Art.\"" }
entries[142352] = { ["name"] = "Kern von Bael'Gar", ["text"] = "Questgegenstand\nBenutzen: Kombiniert einen Kern von Bael'Gar, einen Kern von Roccor, eine Essenz von Incendius und eine Essenz von Magmus in der Schwarzen Schmiede in den Schwarzfelstiefen zu einem Schwarzfelsrubin." }
entries[142353] = { ["name"] = "Kern von Roccor", ["text"] = "Questgegenstand\nBenutzen: Kombiniert einen Kern von Bael'Gar, einen Kern von Roccor, eine Essenz von Incendius und eine Essenz von Magmus in der Schwarzen Schmiede in den Schwarzfelstiefen zu einem Schwarzfelsrubin." }
entries[142354] = { ["name"] = "Essenz von Incendius", ["text"] = "Questgegenstand\nBenutzen: Kombiniert einen Kern von Bael'Gar, einen Kern von Roccor, eine Essenz von Incendius und eine Essenz von Magmus in der Schwarzen Schmiede in den Schwarzfelstiefen zu einem Schwarzfelsrubin." }
entries[142355] = { ["name"] = "Essenz von Magmus", ["text"] = "Questgegenstand\nBenutzen: Kombiniert einen Kern von Bael'Gar, einen Kern von Roccor, eine Essenz von Incendius und eine Essenz von Magmus in der Schwarzen Schmiede in den Schwarzfelstiefen zu einem Schwarzfelsrubin." }
entries[142356] = { ["name"] = "Wischhauchwickel", ["text"] = "Wird beim Aufheben gebunden\n\"Wird verwendet, um verwundete Druiden an der Smaragdgrünen Bucht zu heilen.\"" }
entries[142357] = { ["name"] = "Pläne: Dämmerungsschneide", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Dämmerungsschneide.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nDämmerungsschneide\nWird beim Anlegen gebunden\nEinhändig Axt\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Thoriumbarren (30), Verzauberter Thoriumbarren (4), Sternrubin (4), Blauer Saphir (4), Verdichteter Schleifstein (2), Unverwüstliches Leder (4)" }
entries[142358] = { ["name"] = "Pläne: Loderflammenrapier", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Loderflammenrapiers.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nLoderflammenrapier\nWird beim Anlegen gebunden\nEinhändig Schwert\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\nTrefferchance: Verbrennt den Feind und fügt ihm im Verlauf von 30 Sek. 2 Schaden zu.\nVerkaufspreis:\nBenötigt Verzauberter Thoriumbarren (10), Essenz des Feuers (4), Herz des Feuers (4), Azerothischer Diamant (2), Verdichteter Schleifstein (2)" }
entries[142359] = { ["name"] = "Lavaöl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Macht das Ziel immun gegen die Auswirkungen von Lavaschaden in der Schlackengrube.\nVerkaufspreis:" }
entries[142361] = { ["name"] = "Elfenbeinfarbene Klaue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Heilt 100% Eurer maximalen Gesundheit und macht Euch zum Rächer von Aviana. Während Ihr verwandelt seid, seid Ihr allen Spielercharakteren feindlich gesinnt und das Töten anderer Spielercharaktere gewährt Male der Beute. Kann nur in Bereichen für Falkosaurier- und PvP-Weltquests verwendet werden und markiert Euch für den PvP-Kampf. (15 Min Abklingzeit)\n\"Wenn Ihr die Kralle haltet, verspürt Ihr ein Verlangen, Beute in den Händen zu halten und in Teile zu zerreißen.\"\nVerkaufspreis:" }
entries[142363] = { ["name"] = "Mal der Beute", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht den Ruf bei der Rache der Kralle um 100.\n\"Das Symbol einer erfolgreichen Jagd.\"" }
entries[142364] = { ["name"] = "Tasche mit Zweigen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Baut für 5 Min. ein Nest als Ruhestatt auf. Wenn Ihr mindestens 5 Sek. ruht, seid Ihr gut erholt und alle Eure Werte werden 1 Stunde lang um 3% erhöht. Kann nur auf den Verheerten Inseln genutzt werden. (5 Min Abklingzeit)\nBenötigt Rache der Kralle\n- Freundlich\nVerkaufspreis:" }
entries[142365] = { ["name"] = "Prachtvoller Mantel", ["text"] = "Questgegenstand\n\"Ein Outfit ist niemals vollständig ohne ein Paar beeindruckender Schultern.\"" }
entries[142366] = { ["name"] = "Wiedergekäutes Blatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Esst das Blatt und regeneriert 30 Sek. lang alle 3 Sek. 10% der maximalen Gesundheit. Kann nur auf den Verheerten Inseln genutzt werden. (5 Min Abklingzeit)\nBenötigt Rache der Kralle\n- Neutral\n\"Möglicherweise besser, als zu verhungern.\"\nVerkaufspreis:" }
entries[142367] = { ["name"] = "Elfenbeinfarbene Feder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt Euch in einen Rächer von Aviana. Wenn Ihr in diesem Zustand andere Spielercharaktere tötet, besteht eine Chance, Male der Beute zu erhalten. Kann nur auf Schlachtfeldern und in Ashran verwendet werden. (1s Abklingzeit) (10 Min Abklingzeit)\nBenötigt Rache der Kralle\n- Wohlwollend\n\"Die Winde sprechen aus ganz Azeroth mit Aviana.\"\nVerkaufspreis:" }
entries[142368] = { ["name"] = "Zersplitterter Falkosaurierschnabel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenutzen: Erhöht für 15 Sek. die Chance, einen kritischen Treffer zu erzielen oder zu erleiden, um 50%. Kann nur in Bereichen für Falkosaurier- und PvP-Weltquests verwendet werden. (3 Min Abklingzeit)\nBenötigt Rache der Kralle\n- Respektvoll\n\"Eine Erinnerung an vergangene Taten.\"\nVerkaufspreis:" }
entries[142369] = { ["name"] = "Elfenbeinfarbener Falkenschreiter", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren elfenbeinfarbenen Falkenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Rache der Kralle\n- Ehrfürchtig\nVerkaufspreis:\n\"Meine geflügelten Kinder füllen die Lüfte. Dieses allerdings nicht.\"-Aviana\nVerkäufer:\nKinkerlitz\nZone:\nDer Hochberg\nKosten:" }
entries[142370] = { ["name"] = "Pläne: Arkanitchampion", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Arkanitchampions.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nArkanitchampion\nWird beim Anlegen gebunden\nZweihändig Schwert\n7 - 12 Schaden Geschwindigkeit 3.60\n(2.6 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nTrefferchance: Sich selbst um 6 heilen und Stärke 30 Sek. lang um 2 erhöhen.\nVerkaufspreis:\nBenötigt Arkanitbarren (15), Azerothischer Diamant (8), Rechtschaffene Kugel , Großer Opal (4), Verzaubertes Leder (8), Verdichteter Schleifstein (2)" }
entries[142372] = { ["name"] = "Fein geschnittene Roben", ["text"] = "Questgegenstand\n\"Die feingewobene Seide duftet stark nach Parfüm.\"" }
entries[142374] = { ["name"] = "Extraordinärer Hut", ["text"] = "Questgegenstand\n\"Die Krempe ist trotz Lobos' vielen fehlgeschlagenen Versuchen bei der Prüfung des Feuers nur leicht angesengt.\"" }
entries[142375] = { ["name"] = "Entzauberungskristall", ["text"] = "Questgegenstand\nBenutzen: Entfernt die Maskerade vom nächsten Spitzel der Nachtgeborenen. (5 Sek. Abklingzeit)" }
entries[142377] = { ["name"] = "Völlig zerstörter Dunkelspeer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Schmiedekunst (1)\n\"Dieser Speer scheint als Kauspielzeug von einer der Kreaturen in dieser Gegend verwendet worden zu sein.\"" }
entries[142379] = { ["name"] = "Pflichtbewusster Knappe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ehrestufe 20.\nBenötigt Ehrestufe 5.\nVerkaufspreis:" }
entries[142380] = { ["name"] = "Pflichtbewusster Grunzling", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Ehrestufe 5.\nVerkaufspreis:" }
entries[142381] = { ["name"] = "Lehnseid", ["text"] = "Wird beim Aufheben gebunden\n\"An Euch adressiert.\"\n<Zum Öffnen rechtsklicken>" }
entries[142382] = { ["name"] = "Infiltrationspläne", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nNur von Klassen genutzt, die über eine Tank-Spezialisierung verfügen.\n\"Zwar schwer zu entziffern, doch es ist anscheinend ein Plan zur Unterwanderung Dalarans!\"" }
entries[142383] = { ["name"] = "Pläne: Dunkelspeer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Dunkelspeers.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nDunkelspeer\nWird beim Anlegen gebunden\nZweihändig Stangenwaffe\n6 - 13 Schaden Geschwindigkeit 3.60\n(2.6 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nTrefferchance: Gruppenmitglieder haben eine Chance, ihren kritischen Trefferwert um 17 zu erhöhen. Hält 20 Sek. lang an.\nVerkaufspreis:\nBenötigt Verzauberter Thoriumbarren (20), Mächtiges Mojo (20), Gewaltiger Smaragd (2), Azerothischer Diamant (2), Verdichteter Schleifstein (2)" }
entries[142384] = { ["name"] = "Ausgelaugter Netherkristall", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dieser runenbeschriebene Kristall pulsiert schwach durch die Überreste dunkler Energie.\"" }
entries[142385] = { ["name"] = "Gestohlener verzauberter Thoriumbarren", ["text"] = "Questgegenstand\n\"Diese Barren wurden aus den Lagern im Krater von Un'Goro entwendet und sollten sich bestens für Schmiede zur Weiterverarbeitung eignen.\"" }
entries[142386] = { ["name"] = "Größtenteils mächtiges Mojo", ["text"] = "Questgegenstand\n\"Mindestens so stark wie mächtiges Mojo... naja, fast.\"" }
entries[142387] = { ["name"] = "Versteinerte Dimetrodonschuppe", ["text"] = "Questgegenstand\n\"Kann zur Not einen gewaltigen Smaragd ersetzen.\"" }
entries[142388] = { ["name"] = "Gebleichter Stegodonstachel", ["text"] = "Questgegenstand\n\"Schneeweiß und fast so hart wie Diamant.\"" }
entries[142389] = { ["name"] = "Zerbrochener Dunkelspeer", ["text"] = "Questgegenstand\nBenutzen: Zerlegt den Dunkelspeer, um so an das Wissen zu gelangen, das für seine Herstellung verwendet wurde." }
entries[142392] = { ["name"] = "Instruktionen eines Diebes", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"In dieser hastig geschriebenen Notiz geht es um den Diebstahl der fokussierenden Iris.\"\n<Zum Lesen rechtsklicken>" }
entries[142393] = { ["name"] = "Teufelskristall", ["text"] = "Questgegenstand\n\"Strahlt Teufelsenergie aus.\"" }
entries[142394] = { ["name"] = "\"Uralte\" elfische Kriegsbefehle", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Auf den ersten Blick ein authentischer Befehl, einen feindlichen Außenposten zu zerstören, auf den zweiten Blick strahlt er jedoch Teufelsmagie aus und ist jüngeren Datums.\"" }
entries[142395] = { ["name"] = "Teufelserfülltes Totemfragment", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Teil eines Taurentotems, das von Teufelsenergie nur so trieft. Es kann nur vom Hochberg stammen.\"" }
entries[142396] = { ["name"] = "Beschädigtes Insigne der Kirin Tor", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Der Name 'Levia Laurence' ist eingraviert.\"" }
entries[142397] = { ["name"] = "Vergoldeter Schriftrollenbehälter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Zeichen auf diesem Behältnis scheinen Vrykulrunen zu sein.\"" }
entries[142398] = { ["name"] = "Dunkelwasserrochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr dieses Reittier herbeiruft. Kann nur in einer aquatischen Umgebung beschworen werden.\nBeschwört einen reitbaren Dunkelwasserrochen oder gibt ihn wieder frei.\n\nLässt sich nur unter Wasser einsetzen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Über diese scheue Rochenart ist nur wenig bekannt. Sie wurde bisher nur in den dunklen Gewässern um die Dunkelmond-Insel herum gesichtet.\"\nVerkäufer:\nGalissa Sonnentau\nZone:\nDunkelmond-Insel" }
entries[142399] = { ["name"] = "Experimentelle Zielfindungskugel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Befehlt Euren Verdorrten, ihren Widerstand gegen Teufelsmagie auf die Probe zu stellen. (5 Sek. Abklingzeit)" }
entries[142400] = { ["name"] = "Fortgeschrittene Zielfindungskugel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Befehlt Euren widerstandsfähigen Verdorrten, ihren Widerstand gegen Teufelsmagie auf die Probe zu stellen. (5 Sek. Abklingzeit)" }
entries[142401] = { ["name"] = "Telemantische Kugeln", ["text"] = "Einzigartig\nBenutzen: Schleudert eine telemantische Kugel an den Zielort und ruft dort hungernde Verdorrte herbei. Funktioniert nur im Adelsviertel von Suramar. (45 Sek. Abklingzeit)\n\"Ein Trupp aus Verdorrten, der sofort erscheint.\"" }
entries[142402] = { ["name"] = "Pläne: Leichte erdgeschmiedete Klinge", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer leichten erdgeschmiedeten Klinge.\nBenötigt Klassische Schmiedekunst (1)\nVerkaufspreis:\nLeichte erdgeschmiedete Klinge\nWird beim Aufheben gebunden\nEinhändig Schwert\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Mithrilbarren (12), Erdenkern (4)\nOptionale Reagenzien: [] (#31)" }
entries[142403] = { ["name"] = "Bulliger Basilisk des Grubenkämpfers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren bulligen Basilisken des Grubenkämpfers oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Stacheln auf dieser Bestie können Plattenrüstungen mit Leichtigkeit durchdringen. Nur die bestausgebildetsten Reiter können überhaupt daran denken, auf diesem tödlichen Nadelkissen zu sitzen.\"\nVerkäufer:\nQuackenbusch\nZone:\nDie Tiefenbahn\nKosten:\n\nVerkäufer:\nPaul Norden\nZone:\nShlae'gararena\nKosten:" }
