entries[142406] = { ["name"] = "Trommeln des Berges", ["text"] = "Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\nWirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[142407] = { ["name"] = "Muster: Trommeln des Berges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Trommeln des Berges.\nStellt Trommeln des Berges her.\nBenötigt Lederverarbeitung der Verheerten Inseln (1)\nVerkaufspreis:\nTrommeln des Berges\nBenutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\nWirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Steinbalgleder (10), Intakte Kralle (5), Intakter Zahn (5)" }
entries[142408] = { ["name"] = "Muster: Trommeln des Berges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Trommeln des Berges.\nVerringert die erforderlichen Materialien zur Herstellung von Trommeln des Berges.\nBenötigt Lederverarbeitung der Verheerten Inseln (1)\nBenötigt Der Hochbergstamm\n- Respektvoll\nVerkaufspreis:\nTrommeln des Berges\nBenutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\nWirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Steinbalgleder (8), Intakte Kralle (3), Intakter Zahn (3)" }
