entries[142436] = { ["name"] = "Manasäbler des Arkanisten", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nManasäbler des Arkanisten : Beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Nachtsüchtigen\n- Ehrfürchtig\n\n\"Nach ihrer Rückkehr in die Nachtfestung, verfügte die Erste Arkanistin Thalyssra, dass Abenteurer, die ihre Befreiung Suramars unterstützt hatten, mit kostbaren Reittieren aus den königlichen Ställen gewürdigt wurden.Das Beschwören dieses Reittiers im Stadtgebiet Suramars löst 'Maskerade' aus.\"\nQuest:\nDas Schicksal der Nachtgeborenen\nZone:\nSuramar" }
entries[142437] = { ["name"] = "Boshafter Kriegsskorpion", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegsskorpion oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ist von so ziemlich allen Seiten gesehen stachelig und spitz.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
