entries[142449] = { ["name"] = "Ausgegrabenes Stabkopfstück", ["text"] = "Wird beim Aufheben gebunden\n\"Der Stab verrottet schon lange, doch im mysteriösen Kopfstück pulsiert noch immer Macht.\"\nVerkaufspreis:" }
