entries[142526] = { ["name"] = "Gleve der Gefallenen", ["text"] = "Wird an Kriegsmeute gebunden\nEinhändig Kriegsgleve\n5 - 8 Schaden Geschwindigkeit 2.60\n(2.5 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
