entries[142528] = { ["name"] = "Kiste mit Schwimmern: Dose Würmer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ersetzt 1 Stunde lang Euren Schwimmer mit einer Dose (zumindest für Fische) schmackhafter Würmer. (15 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\nVerkaufspreis:" }
