entries[142534] = { ["name"] = "Daune der gefallenen Val'kyr", ["text"] = "Wird beim Aufheben gebunden\n\"Obwohl die Dunkelheit sich hineingedrängt hat, ist die zugrunde liegende Macht nicht betroffen.\"\nVerkaufspreis:" }
entries[142535] = { ["name"] = "Seelenfänger des aufziehenden Nebels", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Seele zu ergreifen, während sie die Schwelle überschreitet, ist eine widerwärtige Tat und mächtige Talismane machen es nur noch schlimmer.\"\nVerkaufspreis:" }
entries[142536] = { ["name"] = "Würfel der Erinnerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört den Würfel der Erinnerung und erlebt entscheidende Momente in der Schlacht gegen die Legion erneut. (10 Min Abklingzeit)\n\"Im Würfel hallen Erinnerungen an vergangene Zeiten wider.\"" }
