entries[142552] = { ["name"] = "Glimmender Glutwyrm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren glimmenden Glutwyrm oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Arkanagos versuchte, Medivh von seinen arkanen Experimenten abzubringen, doch der Einfluss von Sargeras hatte den Magier bereits ins Mark verderbt und so musste der edle Großdrache für seine Überschreitung mit flammender, nie endender Höllenqual bezahlen.\"\nZone:\nRückkehr nach Karazhan" }
entries[142553] = { ["name"] = "Büschel Zwergenbarthaar", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Es ist wunderbar dicht und füllig und wird als Erfolgsbeweis für Eure Champions dienen.\"" }
