entries[142555] = { ["name"] = "Aoires Gehstock", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser uralte Stab eines berühmten Anführers ist erfüllt von Jahren der Hingabe und Sorge um die Bedürfnisse anderer.\"\nVerkaufspreis:" }
entries[142559] = { ["name"] = "Mysteriöser Würfel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Es scheint, als wäre der Würfel eine Art Transportmittel für Magie, die schon lange verschwunden ist. Vielleicht weiß jemand in Dalaran mehr darüber...\"" }
